INSERT INTO `practical_task` (`id`,`course_id`,`title`,`description`,`competency_code`,`competency_name`) VALUES
('687a171a-5648-5007-b6dc-bf58462c6f7c','54d6aec9-eb74-5592-bbde-2eb125541d24','Build a perceptron classifier','Build a perceptron classifier. Module type: Supervised learning lab. Typical time 45 minutes. Arabic: بناء مصنف بيرسيبترون','AI-C1','{"en": "Model evaluation and deployment", "ar": "تقييم النماذج والنشر"}'),
('86312c17-e121-5439-a250-dc4e98661e5f','54d6aec9-eb74-5592-bbde-2eb125541d24','Train a neural network for image recognition','Train a neural network for image recognition. Module type: Deep learning lab. Typical time 60 minutes. Arabic: تدريب شبكة عصبية للتعرف على الصور','AI-C2','{"en": "Neural network training", "ar": "تدريب الشبكات العصبية"}'),
('4a8d9f3e-a8a3-576c-b84f-e9d48eb88ed0','54d6aec9-eb74-5592-bbde-2eb125541d24','Implement backpropagation from scratch','Implement backpropagation from scratch. Module type: Deep learning lab. Typical time 90 minutes. Arabic: تنفيذ خوارزمية الانتشار الخلفي من الصفر','AI-C2','{"en": "Neural network training", "ar": "تدريب الشبكات العصبية"}'),
('912ce3a3-f4d6-5707-a13a-88a118464345','54d6aec9-eb74-5592-bbde-2eb125541d24','Tune hyperparameters with grid search','Tune hyperparameters with grid search. Module type: Model optimization lab. Typical time 60 minutes. Arabic: ضبط المعاملات الفائقة بالبحث الشبكي','AI-C2','{"en": "Neural network training", "ar": "تدريب الشبكات العصبية"}'),
('1ceba3a1-20da-5873-85b7-164aefe9cc60','54d6aec9-eb74-5592-bbde-2eb125541d24','Evaluate model performance and prepare deployment','Evaluate model performance and prepare deployment. Module type: Model evaluation lab. Typical time 30 minutes. Arabic: تقييم أداء النموذج والتحضير للنشر','AI-C1','{"en": "Model evaluation and deployment", "ar": "تقييم النماذج والنشر"}'),
('4dd7f6cf-cba2-5baa-9ae3-d8ebcbee116b','4b2bd857-87a7-5abe-8342-4c8a6ac1aa1f','Provision a virtual machine on the cloud','Provision a virtual machine on the cloud. Module type: Cloud infrastructure lab. Typical time 40 minutes. Arabic: تشغيل آلة افتراضية على السحابة','IT-C1','{"en": "Cloud operations and administration", "ar": "عمليات وإدارة السحابة"}'),
('aa42f7c1-898d-5bf1-9263-e668087294a2','4b2bd857-87a7-5abe-8342-4c8a6ac1aa1f','Configure a secure VPC network','Configure a secure VPC network. Module type: Networking lab. Typical time 20 minutes. Arabic: إعداد شبكة افتراضية خاصة آمنة','IT-C1','{"en": "Cloud operations and administration", "ar": "عمليات وإدارة السحابة"}'),
('336688b2-9367-5425-bd1c-da1dfe9e03da','4b2bd857-87a7-5abe-8342-4c8a6ac1aa1f','Set up a CI/CD pipeline','Set up a CI/CD pipeline. Module type: DevOps lab. Typical time 45 minutes. Arabic: إعداد خط أنابيب CI/CD','IT-C1','{"en": "Cloud operations and administration", "ar": "عمليات وإدارة السحابة"}'),
('4ba06f1a-4fd0-50ae-a593-fe11b9caa8bc','4b2bd857-87a7-5abe-8342-4c8a6ac1aa1f','Automate infrastructure with code','Automate infrastructure with code. Module type: DevOps lab. Typical time 180 minutes. Arabic: أتمتة البنية التحتية بالكود','IT-C2','{"en": "DevOps and automation", "ar": "ديف أوبس والأتمتة"}'),
('d8a6ce17-ada2-59b4-a5d6-82c925e21f38','4b2bd857-87a7-5abe-8342-4c8a6ac1aa1f','Monitor systems with logging and alerts','Monitor systems with logging and alerts. Module type: Site reliability lab. Typical time 40 minutes. Arabic: مراقبة الأنظمة بالسجلات والتنبيهات','IT-C2','{"en": "DevOps and automation", "ar": "ديف أوبس والأتمتة"}'),
('19f316e9-641a-5ed9-a352-d208754578ef','35bb6485-8bc6-5f27-8a73-43d2ba177953','Collect and clean raw datasets','Collect and clean raw datasets. Module type: Data wrangling lab. Typical time 30 minutes. Arabic: جمع وتنظيف مجموعات البيانات الخام','DS-C1','{"en": "Data wrangling and visualization", "ar": "معالجة البيانات وتصورها"}'),
