-- P6-C student training seed (synthetic data). Generated by generate_student_data.py
-- Target: MySQL 8.0.13+ with the compact ERD v0.3 schema (database p6c_workshop).
-- WARNING: this script REPLACES all training data (courses, tasks, sessions, students, mentors, the supervisor,
-- enrollments, attendance, assessments and certificates). It does not touch workshop tables, and it keeps existing bays.
SET NAMES utf8mb4;
SET SQL_SAFE_UPDATES = 0;
SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM certificate;
DELETE FROM assessment;
DELETE FROM attendance;
DELETE FROM enrollment;
DELETE FROM hall_booking WHERE source = 'SESSION';
DELETE FROM training_session;
DELETE FROM practical_task;
DELETE FROM course;
DELETE FROM app_user WHERE role IN ('STUDENT','MENTOR','TRAINING_SUPERVISOR') AND is_synthetic = 1;
SET FOREIGN_KEY_CHECKS = 1;

-- bay: 4 rows

-- app_user: 45 rows

-- course: 4 rows

-- practical_task: 20 rows

-- training_session: 40 rows

-- bay_booking: 40 rows

-- enrollment: 40 rows

